DROP POLICY "Org owners manage custom roles" ON public.org_custom_roles;
DROP POLICY "Org staff read custom roles" ON public.org_custom_roles;

CREATE POLICY "Org staff can read custom roles" ON public.org_custom_roles
FOR SELECT TO authenticated USING(public.can_access_organization(organization_id,'staff.read'));
CREATE POLICY "Org staff can insert custom roles" ON public.org_custom_roles
FOR INSERT TO authenticated WITH CHECK(public.can_access_organization(organization_id,'staff.write'));
CREATE POLICY "Org staff can update custom roles" ON public.org_custom_roles
FOR UPDATE TO authenticated USING(public.can_access_organization(organization_id,'staff.write'))
WITH CHECK(public.can_access_organization(organization_id,'staff.write'));
CREATE POLICY "Org staff can delete custom roles" ON public.org_custom_roles
FOR DELETE TO authenticated USING(public.can_access_organization(organization_id,'staff.write'));
